type Dict = Record<string, unknown>;

function isPlainObject(value: unknown): value is Dict {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

// Recursively merge `source` into `target` (mutating target) and return it.
// Plain-object values merge deep; anything else overwrites.
// BUG: keys named __proto__ / constructor / prototype are merged like any
// other key, so untrusted input such as JSON.parse('{"__proto__":
// {"isAdmin": true}}') walks into Object.prototype and pollutes every
// object in the process (prototype-pollution vulnerability).
export function deepMerge(target: Dict, source: Dict): Dict {
  for (const key of Object.keys(source)) {
    const value = source[key];
    if (isPlainObject(value) && isPlainObject(target[key])) {
      deepMerge(target[key] as Dict, value);
    } else {
      target[key] = value;
    }
  }
  return target;
}

test_setup_files.behavior_test.js:
const assert = require("assert");
const { deepMerge } = require("./build/merge.js");

// legitimate deep merge still works
const target = { a: 1, nested: { x: 1 } };
deepMerge(target, JSON.parse('{"b": 2, "nested": {"y": 2}}'));
assert.deepStrictEqual(target, { a: 1, b: 2, nested: { x: 1, y: 2 } });

// top-level pollution attempt
deepMerge({}, JSON.parse('{"__proto__": {"pollutedA": true}}'));
const probeA = {};
assert.strictEqual(
  probeA.pollutedA,
  undefined,
  "top-level __proto__ payload polluted Object.prototype"
);

// nested pollution attempt - must be blocked at every depth
deepMerge({ profile: {} }, JSON.parse('{"profile": {"__proto__": {"pollutedB": true}}}'));
const probeB = {};
assert.strictEqual(
  probeB.pollutedB,
  undefined,
  "nested __proto__ payload polluted Object.prototype"
);

console.log("behavior OK");

reference_solution.merge.ts:
type Dict = Record<string, unknown>;

const FORBIDDEN_KEYS = new Set(["__proto__", "constructor", "prototype"]);

function isPlainObject(value: unknown): value is Dict {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

// Recursively merge `source` into `target` (mutating target) and return it.
// Plain-object values merge deep; anything else overwrites. Keys that could
// walk into the prototype chain (__proto__ / constructor / prototype) are
// skipped at EVERY level so untrusted input cannot pollute Object.prototype.
export function deepMerge(target: Dict, source: Dict): Dict {
  for (const key of Object.keys(source)) {
    if (FORBIDDEN_KEYS.has(key)) {
      continue;
    }
    const value = source[key];
    if (isPlainObject(value) && isPlainObject(target[key])) {
      deepMerge(target[key] as Dict, value);
    } else {
      target[key] = value;
    }
  }
  return target;
}

