type Dict = Record<string, unknown>;

function isPlainObject(value: unknown): value is Dict {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function mergeInner(target: Dict, source: Dict): Dict {
  for (const key of Object.keys(source)) {
    const value = source[key];
    if (isPlainObject(value) && isPlainObject(target[key])) {
      mergeInner(target[key] as Dict, value);
    } else {
      target[key] = value;
    }
  }
  return target;
}

// only guards the FIRST level - {"profile": {"__proto__": ...}} slips through
export function deepMerge(target: Dict, source: Dict): Dict {
  const cleaned: Dict = {};
  for (const key of Object.keys(source)) {
    if (key !== "__proto__" && key !== "constructor" && key !== "prototype") {
      cleaned[key] = source[key];
    }
  }
  return mergeInner(target, cleaned);
}
